Derecho and wind damage","Wildfire claims","Coinsurance"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://southdakotainsuranceappraiser.com/#website","url":"https://southdakotainsuranceappraiser.com/","name":"South Dakota Insurance Appraiser","publisher":{"@id":"https://southdakotainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/#webpage","url":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/","name":"Insurance Appraisal Glossary | ACV, RCV, Umpire","description":"Insurance appraisal glossary with 40+ plain-English terms: actual cash value, coinsurance, depreciation, umpire, derecho, O&P and more.","inLanguage":"en-US","isPartOf":{"@id":"https://southdakotainsuranceappraiser.com/#website"},"about":{"@id":"https://southdakotainsuranceappraiser.com/#business"},"publisher":{"@id":"https://southdakotainsuranceappraiser.com/#business"},"dateModified":"2026-11-14","primaryImageOfPage":{"@type":"ImageObject","@id":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/#primaryimage","url":"https://southdakotainsuranceappraiser.com/assets/img/photos/paperwork.webp","width":960,"height":720},"breadcrumb":{"@id":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/#breadcrumb"},"mainEntity":{"@id":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://southdakotainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Glossary","item":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/"}],"@id":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance appraisal glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Often the first payment on a replacement cost policy, and the full payment on an ACV policy."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while your home is being repaired. Also called loss of use or Coverage D."},{"@type":"DefinedTerm","name":"Agreed value","description":"An endorsement in which the insurer and the owner agree on a property’s value in advance, usually suspending coinsurance."},{"@type":"DefinedTerm","name":"All-risk policy","description":"A policy that covers physical loss from any cause not specifically excluded. Also called open perils."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of the damage. This is what an appraisal panel decides."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either side demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side names to value the loss and work with the other appraiser and the umpire."},{"@type":"DefinedTerm","name":"Coinsurance","description":"A clause requiring you to insure property for a set percentage of its value. Falling short can reduce a claim payment."},{"@type":"DefinedTerm","name":"Collateral damage","description":"Damage to soft metals, screens, vents and other items that helps show hail size, direction and date."},{"@type":"DefinedTerm","name":"Cosmetic damage exclusion","description":"An endorsement, common on metal roofs, that excludes dents or marks that do not affect function."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself and attached structures."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached garages, sheds, fences and similar buildings."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for contents."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy listing limits, deductibles, endorsements and the policy period."},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss you pay before the policy pays."},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and obsolescence."},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm produced by a line of thunderstorms. Eastern South Dakota was hit by one on May 12, 2022."},{"@type":"DefinedTerm","name":"Disinterested","description":"Having no financial or personal stake in the outcome. Many appraisal clauses require appraisers to be disinterested or independent."},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage."},{"@type":"DefinedTerm","name":"Estimate","description":"An itemized list of repairs with quantities and prices. Appraisal panels work from line-item estimates."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the roof edge that traps meltwater, which can then back up under shingles and into the house."},{"@type":"DefinedTerm","name":"Ingress","description":"Water or debris entering a building through an opening, such as one created by wind or hail."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate for one task or material, with a quantity and unit price."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether repairs must reasonably match undamaged areas in color, texture and appearance."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping a roof or drying a basement."},{"@type":"DefinedTerm","name":"Named peril","description":"A policy that covers only the causes of loss listed in it, common for some farm buildings."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for extra costs to meet current building codes during repair or rebuilding."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A contractor’s general costs and margin, often 10% and 10%, added when a project requires coordination of several trades."},{"@type":"DefinedTerm","name":"Pitch","description":"The steepness of a roof, written as rise over 12 inches of run, such as 7/12."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which carriers may request within a set time."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation withheld from the first payment that you can recover after repairs are completed."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer says it is handling a claim while reserving the right to deny coverage later."},{"@type":"DefinedTerm","name":"Scope","description":"The list of damaged items and the work needed to repair them."},{"@type":"DefinedTerm","name":"Square","description":"A roofing unit equal to 100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Sub-limit","description":"A lower limit within a policy for a specific type of loss, such as mold, trees or sewer backup."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or increase amounts in the carrier’s estimate, supported by documentation."},{"@type":"DefinedTerm","name":"Surplus lines","description":"Insurance written by carriers not licensed as standard insurers in the state, often used for hard-to-place risks."},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy clause setting how long you have to file a lawsuit against the insurer."},{"@type":"DefinedTerm","name":"Test square","description":"A marked area of roof, often 10 feet by 10 feet, where hail hits are counted."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers cannot agree on."},{"@type":"DefinedTerm","name":"Wind and hail deductible","description":"A separate deductible for windstorm or hail losses, often a percentage of the dwelling limit."}],"@id":"https://southdakotainsuranceappraiser.com/insurance-appraisal-glossary/#definedtermset"}]}</script>
</head>
